    ulong X2 = x[3], X1 = x[2];

    (void) v; (void) w1; (void) w0; (void) h; (void) l;

    v = UWORD(0x000d00d00d00d00d);

    /* V_6 = C_6 + x V_7  (1 x 1) */
    v = UWORD(0x005b05b05b05b05b) + n_mulhi(X2, v);

    /* V_5 = C_5 + x V_6  (2 x 1) */
    _mp_real_mulhi_2x1(&h, &l, X2, X1, v);
    add_ssaaaa(w1, w0, UWORD(0x0222222222222222), UWORD(0x2222222222222222), h, l);

    /* V_4 = C_4 + x V_5  (2 x 2) */
    _mp_real_mulhi_2x2_sloppy(&h, &l, X2, X1, w1, w0);
    add_ssaaaa(w1, w0, UWORD(0x0aaaaaaaaaaaaaaa), UWORD(0xaaaaaaaaaaaaaaaa), h, l);

    /* V_3 = C_3 + x V_4  (3 x 2) */
    _mp_real_mulhi_3x2(&A[2], &A[1], &A[0], x[3], x[2], x[1],
        w1, w0);
    B[0] = UWORD(0xaaaaaaaaaaaaaaaa);
    B[1] = UWORD(0xaaaaaaaaaaaaaaaa);
    B[2] = UWORD(0x2aaaaaaaaaaaaaaa);
    mpn_add_n(A, A, B, 3);

    /* V_2 = C_2 + x V_3  (3 x 3) */
    flint_mpn_mulhigh_n(T, x + 1, A, 3);
    B[0] = UWORD(0x0000000000000000);
    B[1] = UWORD(0x0000000000000000);
    B[2] = UWORD(0x8000000000000000);
    mpn_add_n(A, T, B, 3);

    /* x^2 V_2 */
    B[0] = UWORD(0);
    B[1] = A[0];
    B[2] = A[1];
    B[3] = A[2];
    flint_mpn_sqrhigh(x2, x, 4);
    flint_mpn_mulhigh_n(T, x2, B, 4);
    cy = mpn_add_n(res, x, T, 4);
    res[4] = 1 + cy;
